def compose(*funcs):
    """ Compose functions to operate in series.

    Returns a function that applies other functions in sequence.

    Functions are applied from right to left so that
    ``compose(f, g, h)(x, y)`` is the same as ``f(g(h(x, y)))``.

    If no arguments are provided, the identity function (f(x) = x) is returned.

    >>> inc = lambda i: i + 1
    >>> compose(str, inc)(3)
    '4'

    See Also:
        pipe
    """
    if not funcs:
        return identity
    if len(funcs) == 1:
        return funcs[0]
    else:
        return Compose(funcs)


def compose_left(*funcs):
    """Compose functions to operate in series, applying from left to right.

    Returns a function that applies other functions in sequence.

    Functions are applied from left to right so that
    ``compose_left(f, g, h)(x)`` is the same as ``h(g(f(x)))``.

    If no arguments are provided, the identity function (f(x) = x) is returned.

    >>> inc = lambda i: i + 1
    >>> double = lambda i: i * 2
    >>> compose_left(inc, double)(3)
    8

    See Also:
        compose, pipe
    """
    if not funcs:
        return identity
    if len(funcs) == 1:
        return funcs[0]
    else:
        return ComposeLeft(funcs)


class ComposeLeft:
    """A callable that composes functions from left to right.

    >>> inc = lambda i: i + 1
    >>> double = lambda i: i * 2
    >>> f = ComposeLeft([inc, double])
    >>> f(3)
    8
    """
    __slots__ = ('funcs',)

    def __init__(self, funcs):
        self.funcs = tuple(funcs)

    def __call__(self, arg, *args):
        for func in self.funcs:
            arg = func(arg, *args)
        return arg

    def __repr__(self):
        return '%s(%r)' % (type(self).__name__, self.funcs)


